package com.cbs.payments;

import static com.cbs.payments.PaymentCaseModels.*;
import com.cbs.access.AccessService;
import com.cbs.accounting.DayCloseService;
import com.cbs.reference.ReferenceDataService;
import com.cbs.tenancy.*;
import com.cbs.tenancy.TenantModels.*;
import java.time.*;
import java.util.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.json.JsonMapper;

@Service
@ConditionalOnProperty(name="cbs.tenancy.enabled",havingValue="true",matchIfMissing=true)
public class PaymentCaseService {
 private static final JsonMapper JSON=JsonMapper.builder().build();
 private final JdbcTemplate jdbc;private final TenantRepository tenants;private final AccessService access;private final ReferenceDataService reference;private final TransactionTemplate tx;
 public PaymentCaseService(JdbcTemplate jdbc,TenantRepository tenants,AccessService access,ReferenceDataService reference,PlatformTransactionManager manager){this.jdbc=jdbc;this.tenants=tenants;this.access=access;this.reference=reference;this.tx=new TransactionTemplate(manager);}
 private Map<String,Object> payment(Actor actor,UUID bank,UUID id){var rows=jdbc.queryForList("SELECT * FROM platform.payment_order WHERE tenant_id=? AND issuer=? AND id=?",bank,actor.issuer(),id);if(rows.isEmpty())throw error("PAYMENT_NOT_FOUND");return rows.getFirst();}
 private PaymentModels.Order order(Map<String,Object> row){return JSON.readValue(row.get("payload").toString(),PaymentModels.Order.class);}
 public Map<String,Object> row(Actor actor,UUID bank,UUID id){PaymentAccess.require(jdbc,actor,bank,PaymentAccess.Capability.READ);var rows=jdbc.queryForList("SELECT c.*,s.display_name AS owner_name,p.state AS payment_state,p.reconciliation_conflict,p.payload->>'reference' AS reference FROM platform.payment_case c JOIN platform.staff_identity s ON s.id=c.owner_id JOIN platform.payment_order p ON p.id=c.payment_id WHERE c.tenant_id=? AND c.issuer=? AND c.id=?",bank,actor.issuer(),id);if(rows.isEmpty())throw error("PAYMENT_CASE_NOT_FOUND");var result=new LinkedHashMap<String,Object>(rows.getFirst());result.put("source",JSON.readTree(result.get("source").toString()));return result;}
 private void due(Tenant bank,LocalDate date){var today=reference.read(bank).businessDate();if(date==null||date.isBefore(today)||date.isAfter(today.plusDays(365)))throw error("PAYMENT_CASE_DUE_INVALID");}
 public UUID open(Actor actor,UUID bankId,UUID key,Open input){PaymentAccess.require(jdbc,actor,bankId,PaymentAccess.Capability.MAKE);return tx.execute(t->{jdbc.query("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",r->{},actor.issuer()+":"+actor.subject()+":"+key);var bank=tenants.get(bankId,true);PaymentAccess.require(jdbc,actor,bankId,PaymentAccess.Capability.MAKE);var old=jdbc.queryForList("SELECT id,tenant_id,source=?::jsonb AS matches FROM platform.payment_case WHERE issuer=? AND opened_by=? AND idempotency_key=?",JSON.writeValueAsString(input),actor.issuer(),actor.subject(),key);if(!old.isEmpty()){if(!bankId.equals(old.getFirst().get("tenant_id"))||!Boolean.TRUE.equals(old.getFirst().get("matches")))throw error("IDEMPOTENCY_CONFLICT");return (UUID)old.getFirst().get("id");}
   if(bank.version()!=input.expectedVersion())throw error("STALE_VERSION");DayCloseService.requireOpen(jdbc,bankId);due(bank,input.dueDate());var p=payment(actor,bankId,input.paymentId());var value=order(p);boolean returned=List.of(Kind.RETURNED_PAYMENT,Kind.PROVIDER_REVERSAL).contains(input.kind());
   if((input.kind()!=Kind.DISPUTE&&input.statementId()==null)||(returned!=(input.lineId()!=null))||(returned&&!p.get("state").equals("SETTLED")))throw error("PAYMENT_CASE_FIELDS_INVALID");
   if(input.statementId()!=null){var documents=jdbc.queryForList("SELECT source FROM platform.statement_import WHERE tenant_id=? AND id=? AND issuer=? AND status='OPEN'",String.class,bankId,input.statementId(),actor.issuer());if(documents.isEmpty()||!JSON.readValue(documents.getFirst(),StatementImportModels.Source.class).ledgerId().equals(value.settlementLedgerId()))throw error("PAYMENT_CASE_FIELDS_INVALID");}
   if(input.lineId()!=null&&!jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.statement_line WHERE tenant_id=? AND batch_id=? AND id=? AND decision_id IS NULL)",Boolean.class,bankId,input.statementId(),input.lineId()))throw error("PAYMENT_CASE_FIELDS_INVALID");
   String group=returned?"kind IN ('RETURNED_PAYMENT','PROVIDER_REVERSAL')":"kind=?";var args=new ArrayList<Object>(List.of(input.paymentId()));if(!returned)args.add(input.kind().name());if(input.kind()!=Kind.DISPUTE&&jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.payment_case WHERE payment_id=? AND "+group+" AND state<>'CANCELLED')",Boolean.class,args.toArray()))throw error("PAYMENT_CASE_EXISTS");
   UUID id=UUID.randomUUID();var owner=access.requireAssignable(actor.issuer(),actor.subject());jdbc.update("INSERT INTO platform.payment_case(id,tenant_id,payment_id,issuer,opened_by,kind,statement_id,line_id,source,idempotency_key,owner_id,due_date) VALUES (?,?,?,?,?,?,?,?,?::jsonb,?,?,?)",id,bankId,input.paymentId(),actor.issuer(),actor.subject(),input.kind().name(),input.statementId(),input.lineId(),JSON.writeValueAsString(input),key,owner.id(),input.dueDate());event(actor,bankId,id,"OPENED",input);changed(actor,bank,"PAYMENT_CASE_OPENED",id);return id;
  });}
 public Map<String,Object> dashboard(Actor actor,UUID bankId,int limit,int offset){PaymentAccess.require(jdbc,actor,bankId,PaymentAccess.Capability.READ);AccessService.page(limit,offset);return tx.execute(t->{var bank=tenants.get(bankId,true);var date=reference.read(bank).businessDate();return Map.of("version",bank.version(),"businessDate",date,"items",jdbc.queryForList("SELECT c.id,c.payment_id,c.kind,c.state,c.version,c.due_date,c.statement_id,c.line_id,s.display_name AS owner_name,p.payload->>'reference' AS reference,p.payload->>'amount' AS amount,(c.state NOT IN ('RESOLVED','CANCELLED') AND c.due_date<greatest(?::date,current_date)) AS overdue FROM platform.payment_case c JOIN platform.staff_identity s ON s.id=c.owner_id JOIN platform.payment_order p ON p.id=c.payment_id WHERE c.tenant_id=? AND c.issuer=? ORDER BY (c.state NOT IN ('RESOLVED','CANCELLED')) DESC,c.due_date,c.id LIMIT ? OFFSET ?",date,bankId,actor.issuer(),limit,offset),"total",jdbc.queryForObject("SELECT count(*) FROM platform.payment_case WHERE tenant_id=? AND issuer=?",Long.class,bankId,actor.issuer()),"overdue",jdbc.queryForObject("SELECT count(*) FROM platform.payment_case WHERE tenant_id=? AND state NOT IN ('RESOLVED','CANCELLED') AND due_date<greatest(?::date,current_date)",Long.class,bankId,date),"uninvestigated",jdbc.queryForList("SELECT p.id,p.state,p.payload->>'reference' AS reference,p.payload->>'amount' AS amount FROM platform.payment_order p WHERE p.tenant_id=? AND p.issuer=? AND (p.state IN ('SUBMITTED','UNKNOWN') OR p.reconciliation_conflict) AND NOT EXISTS(SELECT 1 FROM platform.payment_case c WHERE c.payment_id=p.id AND c.state NOT IN ('RESOLVED','CANCELLED')) ORDER BY p.created_at LIMIT 100",bankId,actor.issuer()));});}
 public Map<String,Object> detail(Actor actor,UUID bankId,UUID id){return tx.execute(t->{var bank=tenants.get(bankId,true);var c=row(actor,bankId,id);var result=new LinkedHashMap<String,Object>();result.put("case",c);result.put("version",bank.version());result.put("businessDate",reference.read(bank).businessDate());result.put("events",jdbc.query("SELECT action,subject,payload,created_at FROM platform.payment_case_event WHERE case_id=? ORDER BY created_at DESC,id LIMIT 100",(r,n)->Map.of("action",r.getString(1),"subject",r.getString(2),"payload",JSON.readTree(r.getString(3)),"at",r.getTimestamp(4).toInstant()),id));return result;});}
 public void note(Actor actor,UUID bankId,UUID id,Note input){PaymentAccess.require(jdbc,actor,bankId,PaymentAccess.Capability.MAKE);tx.executeWithoutResult(t->{var bank=tenants.get(bankId,true);PaymentAccess.require(jdbc,actor,bankId,PaymentAccess.Capability.MAKE);var c=row(actor,bankId,id);if(((Number)c.get("version")).longValue()!=input.caseVersion())throw error("PAYMENT_CASE_STALE");event(actor,bankId,id,"NOTE",input);changed(actor,bank,"PAYMENT_CASE_NOTE",id);});}
 public Map<String,Object> validate(Actor actor,Tenant bank,Change input){PaymentAccess.require(jdbc,actor,bank.id(),PaymentAccess.Capability.READ);var c=row(actor,bank.id(),input.caseId());if(bank.version()!=input.expectedVersion()||((Number)c.get("version")).longValue()!=input.caseVersion())throw error("PAYMENT_CASE_STALE");if(List.of("RESOLVED","CANCELLED","RETURN_PENDING").contains(c.get("state")))throw error("PAYMENT_CASE_STATE_INVALID");var p=payment(actor,bank.id(),(UUID)c.get("payment_id"));var value=order(p);
  if(input.decision()==Decision.ASSIGN||input.decision()==Decision.CARRY)due(bank,input.dueDate());
  if(input.decision()==Decision.ASSIGN){if(input.ownerId()==null)throw error("PAYMENT_CASE_FIELDS_INVALID");var owner=access.staff(input.ownerId(),false);if(!owner.issuer().equals(actor.issuer())||!owner.active())throw error("PAYMENT_ACCESS_DENIED");PaymentAccess.require(jdbc,new Actor(actor.issuer(),owner.subject(),false,actor.correlationId()),bank.id(),PaymentAccess.Capability.MAKE);}
  else if(input.ownerId()!=null)throw error("PAYMENT_CASE_FIELDS_INVALID");
  if(input.decision()==Decision.CARRY){DayCloseService.requireOpen(jdbc,bank.id());if(!c.get("state").equals("OPEN")||!c.get("kind").equals("SETTLEMENT_DELAY")||!List.of("SUBMITTED","UNKNOWN").contains(p.get("state"))||Boolean.TRUE.equals(p.get("reconciliation_conflict"))||!jdbc.queryForObject("SELECT completed FROM platform.account_operation WHERE request_id=?",Boolean.class,c.get("payment_id")))throw error("PAYMENT_CARRY_INVALID");
   var doc=jdbc.queryForMap("SELECT source,status FROM platform.statement_import WHERE id=?",c.get("statement_id"));var source=JSON.readValue(doc.get("source").toString(),StatementImportModels.Source.class);if(!doc.get("status").equals("OPEN")||value.businessDate().isBefore(source.fromDate())||value.businessDate().isAfter(source.toDate())||!source.toDate().equals(reference.read(bank).businessDate())||jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.statement_line WHERE batch_id=? AND source->>'type'='PAYOUT' AND source->>'paymentReference'=?)",Boolean.class,c.get("statement_id"),value.reference()))throw error("PAYMENT_CARRY_INVALID");
  }
  if(input.decision()==Decision.CANCEL&&!c.get("state").equals("OPEN"))throw error("PAYMENT_CASE_STATE_INVALID");
  if(input.decision()==Decision.RESOLVE){if(!List.of("SETTLED","REFUNDED","RETURNED").contains(p.get("state"))||Boolean.TRUE.equals(p.get("reconciliation_conflict")))throw error("PAYMENT_CASE_UNRESOLVED");if(List.of("RETURNED_PAYMENT","PROVIDER_REVERSAL").contains(c.get("kind")))throw error("PAYMENT_RETURN_REQUIRED");}
  return c;
 }
 public Map<String,Object> values(Actor actor,Tenant bank,Change input){var c=validate(actor,bank,input);return Map.of("case",c,"decision",input);}
 public void apply(Actor actor,UUID bankId,Change input,UUID approval){PaymentAccess.require(jdbc,actor,bankId,PaymentAccess.Capability.APPROVE);var bank=tenants.get(bankId,true);var c=validate(actor,bank,input);if(actor.subject().equals(c.get("opened_by")))throw error("PAYMENT_CASE_INDEPENDENT_REVIEW");String state=c.get("state").toString();LocalDate from=c.get("effective_from")==null?null:((java.sql.Date)c.get("effective_from")).toLocalDate(),end=null;var p=payment(actor,bankId,(UUID)c.get("payment_id"));
  if(input.decision()==Decision.CARRY){state="CARRIED";from=order(p).businessDate();}
  if(input.decision()==Decision.CANCEL)state="CANCELLED";
  if(input.decision()==Decision.RESOLVE){state="RESOLVED";end=p.get("state").equals("REFUNDED")?jdbc.queryForObject("SELECT (payload->'change'->>'businessDate')::date FROM platform.account_operation WHERE request_id=?",LocalDate.class,p.get("refund_id")):jdbc.queryForObject("SELECT (s.payload->>'settlementDate')::date FROM platform.payment_resolution r JOIN platform.payment_statement s ON s.id=r.statement_id WHERE r.payment_id=?",LocalDate.class,c.get("payment_id"));}
  if(input.decision()==Decision.RESOLVE&&from!=null&&jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.statement_import WHERE tenant_id=? AND ledger_id=? AND status='CLOSED' AND (source->>'toDate')::date>=? AND (source->>'toDate')::date>=?)",Boolean.class,bankId,order(p).settlementLedgerId(),from,end))throw error("PAYMENT_CARRY_CLOSED_PERIOD");
  jdbc.update("UPDATE platform.payment_case SET state=?,owner_id=?,due_date=?,effective_from=?,resolved_date=?,version=version+1,last_decision_id=? WHERE id=?",state,input.ownerId()==null?c.get("owner_id"):input.ownerId(),(input.decision()==Decision.ASSIGN||input.decision()==Decision.CARRY)?input.dueDate():c.get("due_date"),from,end,approval,input.caseId());event(actor,bankId,input.caseId(),input.decision().name(),Map.of("input",input,"approvalId",approval));changed(actor,bank,"PAYMENT_CASE_"+input.decision(),input.caseId());
 }
 private void event(Actor actor,UUID bank,UUID id,String action,Object payload){jdbc.update("INSERT INTO platform.payment_case_event VALUES (?,?,?,?,?,?::jsonb,clock_timestamp())",UUID.randomUUID(),bank,id,actor.subject(),action,JSON.writeValueAsString(payload));}
 private void changed(Actor actor,Tenant bank,String action,UUID id){tenants.change(bank,bank.status(),bank.displayName(),bank.defaultLanguage());tenants.audit(actor,bank.id(),action,bank.version()+1,bank.status(),bank.status(),"Payment investigation "+id,null,null,Map.of("caseId",id));}
 private static TenantException error(String code){return new TenantException(409,code,"Payment investigation requires attention");}
}
